   else:
    k=expr(re.search(r'\\left\((.*?)\\right\)',op)[1])
    if ':=R_' in op:b[i,:]=b[i,:]+k*b[int(re.findall(r'R_\{(\d)\}',op)[-1])-1,:]
    else:b[i,:]=k*b[i,:]
   if b!=after:errs.append('operation '+op)
